cat >> tests/test_cli.py <<'EOF'


def test_add_records_a_percent_split(run):
    code, out, _ = run(
        "add", "--paid-by", "alice", "--amount", "100.00", "--description", "Groceries",
        "--percent", "alice=50", "--percent", "bob=30", "--percent", "carol=20",
    )  # fmt: skip
    assert code == 0
    assert out == "added #1: 100.00 for Groceries\n"
    _, out, _ = run("balances")
    assert out == "alice 50.00\nbob -30.00\ncarol -20.00\n"


def test_percentages_not_adding_up_are_rejected(run):
    code, _, err = run(
        "add", "--paid-by", "alice", "--amount", "10", "--description", "x",
        "--percent", "alice=50", "--percent", "bob=40",
    )  # fmt: skip
    assert code == 2
    assert "add up to 100" in err
    assert run("list")[1] == ""


def test_malformed_percent_is_rejected(run):
    code, _, err = run("add", "--paid-by", "alice", "--amount", "10", "--description", "x", "--percent", "bob")
    assert code == 2
    assert err.startswith("error:")
    assert run("list")[1] == ""


def test_with_and_percent_cannot_be_combined(run):
    with pytest.raises(SystemExit) as exit_info:
        run(
            "add", "--paid-by", "alice", "--amount", "10", "--description", "x",
            "--with", "bob", "--percent", "bob=100",
        )  # fmt: skip
    assert exit_info.value.code == 2
EOF
python -m pytest -q 2>&1 | tail -3

